begin;
do $$declare u uuid:=gen_random_uuid();v uuid:=gen_random_uuid();fid uuid;bid uuid;vid uuid;req uuid:=gen_random_uuid();a jsonb;b jsonb;f colorwin_private.arcade_flights;g colorwin_private.arcade_flights;g2 colorwin_private.arcade_flights;ts timestamptz;begin
 perform pg_advisory_xact_lock(hashtextextended('colorwin-aviator-shared',94));
 insert into auth.users(id,email,raw_user_meta_data) values(u,u||'@invalid.test','{}'),(v,v||'@invalid.test','{}');
 insert into public.account_wallet_ledger(user_id,amount,source,reference) values(u,100,'test','aviator-shared-test:'||u),(v,100,'test','aviator-shared-test:'||v);
 ts:=clock_timestamp()+interval '30 seconds';
 insert into colorwin_private.arcade_flights(user_id,is_shared,starts_at,crash_at,crash_multiplier) values(null,true,ts,ts+ln(3::double precision)/.18*interval '1 second',3) returning * into f;fid:=f.id;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 a:=public.colorwin_arcade('aviator','load');
 if (a->'round'->>'id')::uuid<>fid or (a->'round'->>'shared')::boolean is not true or a::text like '%crash_at%' or a::text like '%crash_multiplier%' then raise exception 'Shared round missing or future result exposed';end if;
 a:=public.colorwin_arcade('aviator','bet',jsonb_build_object('flight_id',fid,'slot',0,'amount',10,'auto_target',2,'request_id',req));
 bid:=(a->'round'->'bets'->0->>'id')::uuid;
 a:=public.colorwin_arcade('aviator','bet',jsonb_build_object('flight_id',fid,'slot',0,'amount',10,'auto_target',2,'request_id',req));
 if (a->>'balance')::numeric<>90 or jsonb_array_length(a->'round'->'bets')<>1 then raise exception 'Duplicate bet debit';end if;
 begin perform colorwin_private.aviator_current(clock_timestamp());raise exception 'Private helper exposed';exception when insufficient_privilege then null;end;
 execute 'reset role';perform set_config('request.jwt.claims',jsonb_build_object('sub',v,'role','authenticated')::text,true);execute 'set local role authenticated';
 b:=public.colorwin_arcade('aviator','load');
 if b->'round'->>'id'<>a->'round'->>'id' or b->'round'->>'starts_at'<>a->'round'->>'starts_at' or jsonb_array_length(b->'round'->'bets')<>0 then raise exception 'Users do not share clock or private bets leaked';end if;
 if position(u::text in b::text)>0 or jsonb_array_length(b->'live_bets')<1 then raise exception 'Live bets missing or player identity leaked';end if;
 begin perform public.colorwin_arcade('aviator','cash',jsonb_build_object('id',bid));raise exception 'Foreign bet accepted';exception when raise_exception then if sqlerrm<>'Bet not found' then raise;end if;end;
 b:=public.colorwin_arcade('aviator','bet',jsonb_build_object('flight_id',fid,'slot',0,'amount',10,'request_id',gen_random_uuid()));vid:=(b->'round'->'bets'->0->>'id')::uuid;
 if (b->>'balance')::numeric<>90 then raise exception 'Second player cannot use same slot';end if;
 b:=public.colorwin_arcade('aviator','cancel',jsonb_build_object('id',vid));b:=public.colorwin_arcade('aviator','cancel',jsonb_build_object('id',vid));
 if (b->>'balance')::numeric<>100 then raise exception 'Refund not exactly once';end if;
 b:=public.colorwin_arcade('aviator','bet',jsonb_build_object('flight_id',fid,'slot',0,'amount',10,'request_id',gen_random_uuid()));
 execute 'reset role';
 perform colorwin_private.aviator_settle_user(u,f.crash_at+interval '1 second');perform colorwin_private.aviator_settle_user(u,f.crash_at+interval '1 second');
 perform colorwin_private.aviator_settle_user(v,f.crash_at+interval '1 second');
 if (select count(*) from public.account_wallet_ledger where reference='aviator-win:'||bid)<>1 or (select payout from colorwin_private.arcade_bets where id=bid)<>20 then raise exception 'Offline auto payout not exactly once';end if;
 if (select count(*) from colorwin_private.arcade_bets where user_id=v and status='lost' and result=3)<>1 then raise exception 'Shared crash/loss settlement incorrect';end if;
 if (select sum(amount) from public.account_wallet_ledger where user_id=u)<>110 or (select sum(amount) from public.account_wallet_ledger where user_id=v)<>90 then raise exception 'Wallet isolation incorrect';end if;
 g:=colorwin_private.aviator_current(f.crash_at+interval '4 seconds');
 if g.id<>f.id then raise exception 'Crash display ended before five seconds';end if;
 g:=colorwin_private.aviator_current(f.crash_at+interval '5 seconds');g2:=colorwin_private.aviator_current(f.crash_at+interval '5 seconds');
 if g.id=f.id or g.starts_at<>f.crash_at+interval '15 seconds' then raise exception 'Five-second pause or ten-second countdown incorrect';end if;
 if g.growth_rate<>.06 or g.id<>g2.id or abs(extract(epoch from(g.crash_at-g.starts_at))-ln(g.crash_multiplier::double precision)/.06)>.001 then raise exception 'Reference flight pace or shared result unstable';end if;
 if has_function_privilege('anon','public.colorwin_arcade(text,text,jsonb)','execute') then raise exception 'Anonymous arcade access';end if;
end $$;
rollback;
